create or replace function public.create_service_catalogue_item(_service_code text,_service_name text,_department text,_unit text,_amount numeric,_currency text default 'GHS') returns public.service_tariffs language plpgsql security definer set search_path=public as $$ declare r public.service_tariffs; uid uuid:=auth.uid(); actor_department text; target_department text:=lower(trim(coalesce(_department,''))); begin if uid is null then raise exception 'Authentication required'; end if; if not public.current_user_has_catalogue_create_permission('create_services') then raise exception 'Create services privilege required'; end if; select lower(trim(coalesce(p.department,''))) into actor_department from public.profiles p where p.id=uid; if not (public.has_role(uid,'admin') or public.has_role(uid,'it_admin')) and (target_department='' or actor_department='' or target_department<>actor_department) then raise exception 'You may create services only for your department'; end if; if length(trim(coalesce(_service_code,'')))<2 then raise exception 'Service code is required'; end if; if length(trim(coalesce(_service_name,'')))<2 then raise exception 'Service name is required'; end if; if target_department='' then raise exception 'Department is required'; end if; if coalesce(_amount,0)<0 then raise exception 'Service amount cannot be negative'; end if; insert into public.service_tariffs(service_code,service_name,department,unit,amount,active,currency) values(upper(trim(_service_code)),trim(_service_name),target_department,coalesce(nullif(trim(_unit),''),'unit'),coalesce(_amount,0),true,upper(coalesce(nullif(trim(_currency),''),'GHS'))) returning * into r; perform public.record_system_audit('service_catalogue_created','billing','service_tariffs',r.id,'info',jsonb_build_object('service_code',r.service_code,'service_name',r.service_name,'department',r.department,'actor_id',uid)); return r; end; $$; revoke all on function public.create_service_catalogue_item(text,text,text,text,numeric,text) from public,anon; grant execute on function public.create_service_catalogue_item(text,text,text,text,numeric,text) to authenticated; notify pgrst,'reload schema';